import 'package:accounting_software/app/core/foundation/types/api_result.dart';import 'package:accounting_software/app/core/foundation/types/paginated_parser.dart';import 'package:accounting_software/app/core/foundation/types/paginated_result.dart';import 'package:accounting_software/app/core/network/api_client_interface.dart';import 'package:accounting_software/app/features/catalog/genders/data/genders_endpoint.dart';import 'package:accounting_software/app/features/catalog/genders/domain/entity/gender_stats.dart';import 'package:accounting_software/app/core/foundation/types/api_result.dart';class GenderStatsRemoteDataSourceImpl{const GenderStatsRemoteDataSourceImpl(this._api);final IApiClient _api;Future<ApiResult<GenderStats>> getGenderStats()async{final all=await _api.getPaginated<int>(GendersEndpoint.collection,fromJson:(j)=>j['id'] as int,queryParameters:const{'select':'id'},parser:PaginatedParserPresets.supabase,page:1,limit:1);if(all is ApiFailure<PaginatedResult<int>>)return ApiFailure<GenderStats>(all.exception);final total=(all as ApiSuccess<PaginatedResult<int>>).data.totalCount;final activeResult=await _api.getPaginated<int>(GendersEndpoint.collection,fromJson:(j)=>j['id'] as int,queryParameters:const{'select':'id','is_active':'eq.true'},parser:PaginatedParserPresets.supabase,page:1,limit:1);if(activeResult is ApiFailure<PaginatedResult<int>>)return ApiFailure<GenderStats>(activeResult.exception);final active=(activeResult as ApiSuccess<PaginatedResult<int>>).data.totalCount;return ApiSuccess(GenderStats(total:total,active:active,inactive:total-active));}}